"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for stud in students:
        if not stud.email:
            raise ProjectError(
                f"no email for {stud.display_name}"
            )


def _sort_key(stud: Student) -> str:
    return stud.display_name.casefold()


def _cells(stud: Student) -> tuple:
    return (stud.display_name, stud.section, stud.email)


def _widths(rows: list) -> list:
    return [max(map(len, item)) for item in zip(*rows)]


def _line(cells: tuple, widths: list) -> str:
    pairs = zip(cells, widths)
    text = "  ".join(
        cell.ljust(wide) for cell, wide in pairs
    )
    return text.rstrip()


def format_contacts(students: List[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    _check(students)
    ordered = sorted(students, key=_sort_key)
    rows = [_cells(stud) for stud in ordered]
    widths = _widths(rows)
    return [_line(row, widths) for row in rows]

