import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts


def make_student(last, first, section, email):
    return Student("id", last, first, section, email)


class ContactTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        rows = format_contacts([
            make_student("Zane", "Al", "B", "al@x.org"),
            make_student("Adams", "Bo", "A", "bo@x.org")
        ])
        self.assertTrue(rows[0].startswith("Adams, Bo"))
        self.assertTrue(rows[1].startswith("Zane, Al"))

    def test_columns_line_up(self):
        rows = format_contacts([
            make_student("Zane", "Al", "B", "al@x.org"),
            make_student("Adams", "Bo", "A", "bo@x.org")
        ])
        self.assertEqual(rows[0].index("A"), 0)
        self.assertEqual(
            rows[0].index("bo@x.org"),
            rows[1].index("al@x.org")
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as caught:
            format_contacts([
                make_student("Adams", "Bo", "A", None)
            ])
        self.assertIn("Adams, Bo", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            format_contacts([])
